#!/usr/bin/env python3
# LAMWEB 2.99.631 (LENH-631, anh Logan 02/11 17:14): AI dien thoai HOI LUON loai manicure trong cuoc goi.
#  TRUOC: prompt "If a manicure type (dip / gel) is not said, book the basic one - the salon texts the choices" -> sau cuoc goi tin "Reply 1 = Gel, 2 = Dip, 3 = Acrylic".
#  SAU:  - prompt: chua noi loai -> 1 cau "Would you like gel, dip, or acrylic - or just regular polish?"; nhom: "Same for everyone?" (khac -> tung nguoi);
#          "not sure" -> mani_type unsure (ban co ban + tin hoi nhu cu); da noi -> khong hoi lai; pedicure: khong hoi.
#        - tool book: mani_type gel | dip | acrylic | regular | unsure (gia tri cu van chay) + persons[].mani_type (nhom khac loai).
#        - cl_agent_types(): loai -> dich vu NGAY (gel = tin so 1, dip = so 2, acrylic = so 3 Acrylic Gel full set, regular = manicure co ban), KHONG tin hoi;
#          loai chung cua cuoc goi chi cho nguoi CO manicure (nguoi chi pedicure khong bi them).
#  1 file: inc/calls-agent.php. Khong doi DB, khong doi calls-ask / calls-job / calls-tx. AN public_html: khong co file nao.
#  Sau khi len: Settings -> Calls -> Telnyx "Update AI" (prompt + tool moi len Telnyx).
# Run:  python3 fix631.py <app dir>   (kiem)   /   python3 fix631.py <app dir> go
import sys, os, shutil, time, hashlib, json, subprocess
R = sys.argv[1].rstrip('/'); go = len(sys.argv) > 2 and sys.argv[2] == 'go'
def sha(t): return hashlib.sha256(t.encode('utf-8')).hexdigest()[:8]
F = json.loads(r"""{"inc/calls-agent.php": {"base625": "445f8769", "lamweb_test_base": "b2377418", "lamweb_test_new": "0847825d", "A": [["If a manicure type (dip / gel) is not said, book the basic one \u2013 the salon texts the choices.", "MANICURE TYPE (2.99.631): when a manicure's type is not said yet, ask ONE short question: \\\"Would you like gel, dip, or acrylic \u2013 or just regular polish?\\\" A group: ask once \\\"Same for everyone?\\\" \u2013 if not, ask each person's in one short line. Pass it as mani_type (gel | dip | acrylic | regular); people with different types: mani_type on each person. \\\"Not sure\\\" / \\\"I'll decide there\\\" \u2192 mani_type unsure (the basic one is booked, the salon texts the choices). Never ask again a type the caller has said. Pedicure: never ask its type."], ["'mani_type' => ['type' => 'string', 'description' => 'dip | gel_real | gel_fake | gel_unsure | plain | none']", "'mani_type' => ['type' => 'string', 'description' => 'gel | dip | acrylic | regular (just polish) | unsure (not sure \u2013 the salon texts the choices) | none; people with different types: on each person instead']"], ["'tech_id' => ['type' => 'integer', 'description' => 'a tech asked for, else 0']]];", "'tech_id' => ['type' => 'integer', 'description' => 'a tech asked for, else 0'], 'mani_type' => ['type' => 'string', 'description' => 'only when the people want different manicure types: gel | dip | acrylic | regular | unsure']]]; /* (2.99.631) */"], ["$persons = array_values(array_filter((array)($a['persons'] ?? []), 'is_array')); $n = max(1, count($persons));", "$persons = array_values(array_filter((array)($a['persons'] ?? []), 'is_array')); $n = max(1, count($persons));\n    [$persons, $mt] = cl_agent_types($persons, (string)($a['mani_type'] ?? 'none')); /* (2.99.631 - LENH 631) the type said on the call -> the service now, no 1/2/3 text */"], ["'mani_type' => (string)($a['mani_type'] ?? 'none') ?: 'none', 'pedi_type' => (string)($a['pedi_type'] ?? 'none') ?: 'none', 'same_services' => false, 'customer_name' => (string)($a['name'] ?? '')];", "'mani_type' => $mt, 'pedi_type' => (string)($a['pedi_type'] ?? 'none') ?: 'none', 'same_services' => false, 'customer_name' => (string)($a['name'] ?? '')];"], ["/** The AI's people \u2192 [ppl for the checks, j for cl_decide, the label]. */", "/** (2.99.631 - LENH 631, anh Logan 02/11 17:14) The manicure type the AI ASKED on the call -> that service on each person now (no \"Reply 1 / 2 / 3\" text after).\n    gel = the text's \"1 = Gel\" (gel manicure), dip = \"2 = Dip\", acrylic = \"3 = Acrylic\" (the 612n acrylic gel full set), regular = the basic manicure (cla_kinds: the salon's own menu).\n    A type on a person = that person; the call's type = every person who has a manicure (or no service yet) - a person with only a pedicure is not given one.\n    unsure / plain / gel_unsure, or a type the menu does not have -> as before (the basic one + the text, cla_fix in cl_decide). Returns [persons, the call's mani_type for cl_decide]. */\nfunction cl_agent_types(array $persons, string $top): array {\n    $map = ['gel' => 'gel', 'gel_real' => 'gel', 'dip' => 'dip', 'acrylic' => 'acr', 'gel_fake' => 'acr', 'regular' => 'mreg']; $old = ['gel' => 'gel_real', 'acrylic' => 'gel_fake', 'unsure' => 'plain', 'regular' => 'plain'];\n    $low = fn($v) => strtolower(trim((string)$v)); $top = $low($top) ?: 'none'; $leg = $old[$top] ?? $top;\n    if (!$persons) return [$persons, $leg];\n    if (!function_exists('cla_kinds')) require_once __DIR__ . '/calls-ask.php';\n    $K = cla_kinds(); $ask = false;\n    foreach ($persons as $i => $x) {\n        $own = $low($x['mani_type'] ?? ''); $own = $own === 'none' ? '' : $own; $t = $own !== '' ? $own : $top;\n        $ids = array_values(array_unique(array_filter(array_map('intval', (array)($x['service_ids'] ?? [])))));\n        $hand = []; foreach (services_by_ids($ids) as $s) if (!cla_addon($s) && cla_side($s) === 'hand') $hand[] = (int)$s['id'];\n        if ($own === '' && $ids && !$hand) continue; /* only a pedicure (or other): the call's type is not for this person */\n        $k = $map[$t] ?? '';\n        if ($k !== '' && $K[$k]) { $persons[$i]['service_ids'] = array_values(array_unique(array_merge(array_diff($ids, $hand), [$K[$k]]))); continue; }\n        if ($k === 'mreg') continue; /* \"just regular polish\" but no basic manicure on the menu: as the AI booked it, no text */\n        if ($k !== '' || in_array($t, ['unsure', 'plain', 'gel_unsure'], true)) $ask = true; /* not sure / the menu has no such service: the text, as before */\n    }\n    if (!$ask) return [$persons, isset($map[$top]) || $top === 'unsure' ? 'none' : $top];\n    return [$persons, in_array($leg, ['dip', 'gel_real', 'gel_fake', 'gel_unsure', 'plain'], true) ? $leg : 'plain'];\n}\n/** The AI's people \u2192 [ppl for the checks, j for cl_decide, the label]. */"]]}}""")
plan = []; bad = 0
for f, x in F.items():
    p = f'{R}/{f}'; s = open(p, encoding='utf-8').read(); n = [s.count(a) for a, _ in x['A']]
    al = '2.99.631' in s; print(f, 'sha', sha(s), '(live 625 =', x['base625'] + ')', 'anchors', *n, 'already', al)
    if al or n != [1] * len(n): bad = 1; continue
    t = s
    for a, b in x['A']: t = t.replace(a, b)
    plan.append((f, p, t))
if bad: sys.exit('STOP: an anchor is not found exactly once, or already patched - nothing changed')
if not go:
    for f, p, t in plan: print('NEW would be', f, sha(t))
    sys.exit('check only - run again with: go')
bk = os.path.expanduser('~/app/old'); os.makedirs(bk, exist_ok=True); st = time.strftime('%m%d%H%M'); done = []
def back(msg):
    for q, bb in done: shutil.copy2(bb, q)
    sys.exit('ERROR ' + msg + ' - every file put back')
for f, p, t in plan:
    b = f'{bk}/' + f.replace('/', '__') + f'.pre-631-{st}'; shutil.copy2(p, b); m = os.stat(p).st_mode; open(p, 'w', encoding='utf-8').write(t); os.chmod(p, m); done.append((p, b))
    r = subprocess.run(['php', '-l', p], capture_output=True, text=True)
    if r.returncode: back('in ' + p + ': ' + (r.stdout + r.stderr)[:300])
    print('NEW', f, sha(t), 'backup', b)
print('OK 2.99.631 (AI hoi loai mani) - set APP_VERSION 2.99.631, restart php-fpm, roi Settings -> Calls -> Telnyx "Update AI".')
